import sys
input = sys.stdin.readline

def int_num():
	return int(input())

def int_list():
	return list(map(int, input().split()))

def insr():
	s = input()
	return list(s[:len(s) - 1])

def invr():
	return map(int, input().split())

def solve():
	(n, q) = int_list()
	a = int_list()
	d = {}
	(max_id, max_first) = (0, 1)
	(head_id, head_num) = (0, a[0])
	for i in range(1, n):
		if a[i] == n:
			(max_id, max_first) = (i, i)
			break
		if a[i] > head_num:
			(head_id, head_num) = (i, a[i])
		if head_id in d:
			(first, cnt) = d[head_id]
			d[head_id] = (first, cnt + 1)
		else:
			d[head_id] = (i, 1)
	while q:
		(qid, k) = int_list()
		qid = qid - 1
		if qid == max_id:
			ans = 0 if k < max_id else k - max_first + 1
		elif qid in d:
			(first, cnt) = d[qid]
			if k < first:
				ans = 0
			elif k > first + cnt - 1:
				ans = cnt
			else:
				ans = k - first + 1
		else:
			ans = 0
		print(ans)
		q -= 1

def main():
	t = int_num()
	while t:
		solve()
		t -= 1
	return
main()
